-- PHASE B TARGET DRAFT, PART 3: selected required domain specialties.
-- NOT an approved baseline; proposed media/credits/music schemas require owner review.
-- Apply after Parts 1 and 2 ONLY to a new disposable PostgreSQL database.
BEGIN;

CREATE TABLE "EditionExternalIdentities" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "WorkEditionId" bigint NOT NULL,
    "ProviderId" bigint NOT NULL,
    "ProviderNamespace" text NOT NULL,
    "ExternalId" text NOT NULL,
    CONSTRAINT "PK_EditionExternalIdentities" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_EditionExternalIdentities_WorkEditions" FOREIGN KEY ("WorkEditionId") REFERENCES "WorkEditions" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_EditionExternalIdentities_Providers" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_EditionExternalIdentities_ProviderNamespaceId" UNIQUE ("ProviderId","ProviderNamespace","ExternalId")
);
CREATE INDEX "IX_EditionExternalIdentities_WorkEditionId" ON "EditionExternalIdentities" ("WorkEditionId");

CREATE TABLE "People" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "DisplayName" text NOT NULL,
    "SortName" text NOT NULL DEFAULT '',
    CONSTRAINT "PK_People" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_People_DisplayName" CHECK (length(btrim("DisplayName")) > 0)
);

CREATE TABLE "WorkCreditRoleTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_WorkCreditRoleTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_WorkCreditRoleTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_WorkCreditRoleTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_WorkCreditRoleTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "WorkCreditRoleTypes" ("Id", "Key")
VALUES
    (1, 'cast'),
    (2, 'crew'),
    (3, 'author'),
    (4, 'narrator'),
    (5, 'illustrator');
CREATE TABLE "WorkCredits" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "WorkEditionId" bigint NOT NULL,
    "PersonId" bigint NOT NULL,
    "WorkCreditRoleTypeId" smallint NOT NULL,
    "CreditOrder" integer NOT NULL DEFAULT 0,
    "RoleName" varchar(100),
    CONSTRAINT "PK_WorkCredits" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_WorkCredits_Role" UNIQUE NULLS NOT DISTINCT ("WorkEditionId", "PersonId", "WorkCreditRoleTypeId", "RoleName"),
    CONSTRAINT "FK_WorkCredits_WorkEditions" FOREIGN KEY ("WorkEditionId") REFERENCES "WorkEditions" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkCredits_People" FOREIGN KEY ("PersonId") REFERENCES "People" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkCredits_WorkCreditRoleTypes" FOREIGN KEY ("WorkCreditRoleTypeId") REFERENCES "WorkCreditRoleTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_WorkCredits_Order" CHECK ("CreditOrder" >= 0),
    CONSTRAINT "CK_WorkCredits_RoleName" CHECK ("RoleName" IS NULL OR (length("RoleName") > 0 AND "RoleName" = btrim("RoleName")))
);
CREATE INDEX "IX_WorkCredits_Person" ON "WorkCredits" ("PersonId");
CREATE INDEX "IX_People_Sort" ON "People" ("SortName", "Id");

CREATE TABLE "MediaTechnicalAnalyses" (
    "MediaAssetId" bigint NOT NULL,
    "AnalyzedAt" timestamptz NOT NULL DEFAULT now(),
    "DurationMs" bigint,
    "Width" integer,
    "Height" integer,
    "BitRateBps" bigint,
    "SourceFingerprint" text,
    CONSTRAINT "PK_MediaTechnicalAnalyses" PRIMARY KEY ("MediaAssetId"),
    CONSTRAINT "FK_MediaTechnicalAnalyses_MediaAssets" FOREIGN KEY ("MediaAssetId") REFERENCES "MediaAssets" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MediaTechnicalAnalyses_Duration" CHECK ("DurationMs" IS NULL OR "DurationMs" >= 0),
    CONSTRAINT "CK_MediaTechnicalAnalyses_Dimensions" CHECK (
        ("Width" IS NULL AND "Height" IS NULL)
        OR ("Width" IS NOT NULL AND "Height" IS NOT NULL AND "Width" > 0 AND "Height" > 0)),
    CONSTRAINT "CK_MediaTechnicalAnalyses_Bitrate" CHECK ("BitRateBps" IS NULL OR "BitRateBps" >= 0)
);

-- People owns credited identities, including ensembles; MusicArtists adds only artist lifecycle facts.
CREATE TABLE "MusicArtists" (
    "Id" bigint NOT NULL,
    "AddedByProfileId" bigint,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    "LastRefreshedAt" timestamptz,
    CONSTRAINT "PK_MusicArtists" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MusicArtists_People" FOREIGN KEY ("Id") REFERENCES "People" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicArtists_AddedByProfile" FOREIGN KEY ("AddedByProfileId") REFERENCES "Profiles" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MusicArtists_RefreshedAt" CHECK ("LastRefreshedAt" IS NULL OR "LastRefreshedAt" >= "CreatedAt")
);
CREATE INDEX "IX_MusicArtists_AddedByProfile" ON "MusicArtists" ("AddedByProfileId") WHERE "AddedByProfileId" IS NOT NULL;

CREATE TABLE "PersonExternalIdentities" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "PersonId" bigint NOT NULL,
    "ProviderId" bigint NOT NULL,
    "ProviderNamespace" varchar(100) NOT NULL,
    "ExternalId" varchar(500) NOT NULL,
    CONSTRAINT "PK_PersonExternalIdentities" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_PersonExternalIdentities_People" FOREIGN KEY ("PersonId") REFERENCES "People" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_PersonExternalIdentities_Providers" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_PersonExternalIdentities_ProviderIdentity" UNIQUE ("ProviderId", "ProviderNamespace", "ExternalId"),
    CONSTRAINT "UX_PersonExternalIdentities_PersonProvider" UNIQUE ("PersonId", "ProviderId", "ProviderNamespace"),
    CONSTRAINT "CK_PersonExternalIdentities_Namespace" CHECK ("ProviderNamespace" ~ '^[a-z][a-z0-9_]{0,99}$'),
    CONSTRAINT "CK_PersonExternalIdentities_ExternalId" CHECK (length("ExternalId") > 0 AND "ExternalId" = btrim("ExternalId"))
);
CREATE INDEX "IX_PersonExternalIdentities_Provider" ON "PersonExternalIdentities" ("ProviderId");

CREATE TABLE "MusicRecordings" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "DisplayName" text NOT NULL,
    "DurationMs" bigint,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_MusicRecordings" PRIMARY KEY ("Id"),
    CONSTRAINT "CK_MusicRecordings_Name" CHECK (length(btrim("DisplayName")) > 0),
    CONSTRAINT "CK_MusicRecordings_Duration" CHECK ("DurationMs" IS NULL OR "DurationMs" >= 0)
);

CREATE TABLE "MusicRecordingExternalIdentities" (
    "Id" bigint GENERATED BY DEFAULT AS IDENTITY,
    "MusicRecordingId" bigint NOT NULL,
    "ProviderId" bigint NOT NULL,
    "ProviderNamespace" varchar(100) NOT NULL,
    "ExternalId" varchar(500) NOT NULL,
    CONSTRAINT "PK_MusicRecordingExternalIdentities" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_MusicRecordingExternalIdentities_Recordings" FOREIGN KEY ("MusicRecordingId") REFERENCES "MusicRecordings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicRecordingExternalIdentities_Providers" FOREIGN KEY ("ProviderId") REFERENCES "Providers" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "UX_MusicRecordingExternalIdentities_ProviderIdentity" UNIQUE ("ProviderId", "ProviderNamespace", "ExternalId"),
    CONSTRAINT "UX_MusicRecordingExternalIdentities_RecordingProvider" UNIQUE ("MusicRecordingId", "ProviderId", "ProviderNamespace"),
    CONSTRAINT "CK_MusicRecordingExternalIdentities_Namespace" CHECK ("ProviderNamespace" ~ '^[a-z][a-z0-9_]{0,99}$'),
    CONSTRAINT "CK_MusicRecordingExternalIdentities_ExternalId" CHECK (length("ExternalId") > 0 AND "ExternalId" = btrim("ExternalId"))
);
CREATE INDEX "IX_MusicRecordingExternalIdentities_Provider" ON "MusicRecordingExternalIdentities" ("ProviderId");

CREATE TABLE "MusicAlbumTypes" (
    "Id" smallint NOT NULL,
    "Key" text NOT NULL,
    CONSTRAINT "PK_MusicAlbumTypes" PRIMARY KEY ("Id"),
    CONSTRAINT "UX_MusicAlbumTypes_Key" UNIQUE ("Key"),
    CONSTRAINT "CK_MusicAlbumTypes_Id" CHECK ("Id" BETWEEN 0 AND 255),
    CONSTRAINT "CK_MusicAlbumTypes_Key" CHECK (length(btrim("Key")) > 0)
);
INSERT INTO "MusicAlbumTypes" ("Id", "Key")
VALUES
    (1, 'album'),
    (2, 'ep'),
    (3, 'single'),
    (4, 'compilation'),
    (5, 'live'),
    (6, 'soundtrack'),
    (7, 'other');

CREATE TABLE "MusicAlbums" (
    "WorkId" bigint NOT NULL,
    "MusicMediaTypeId" smallint GENERATED ALWAYS AS (6::smallint) STORED,
    "MusicAlbumTypeId" smallint NOT NULL,
    "TrackListWorkEditionId" bigint,
    "CreatedAt" timestamptz NOT NULL DEFAULT now(),
    CONSTRAINT "PK_MusicAlbums" PRIMARY KEY ("WorkId"),
    CONSTRAINT "FK_MusicAlbums_MusicWorks" FOREIGN KEY ("WorkId", "MusicMediaTypeId") REFERENCES "Works" ("Id", "MediaTypeId") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicAlbums_Types" FOREIGN KEY ("MusicAlbumTypeId") REFERENCES "MusicAlbumTypes" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicAlbums_TrackListEdition" FOREIGN KEY ("TrackListWorkEditionId", "WorkId") REFERENCES "WorkEditions" ("Id", "WorkId") ON DELETE RESTRICT
);
CREATE INDEX "IX_MusicAlbums_TrackListEdition" ON "MusicAlbums" ("TrackListWorkEditionId") WHERE "TrackListWorkEditionId" IS NOT NULL;

CREATE TABLE "MusicRecordingArtists" (
    "MusicRecordingId" bigint NOT NULL,
    "MusicArtistId" bigint NOT NULL,
    "CreditOrder" integer NOT NULL DEFAULT 0,
    "CreditName" varchar(200),
    CONSTRAINT "PK_MusicRecordingArtists" PRIMARY KEY ("MusicRecordingId","MusicArtistId"),
    CONSTRAINT "FK_MusicRecordingArtists_MusicRecordings" FOREIGN KEY ("MusicRecordingId") REFERENCES "MusicRecordings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicRecordingArtists_MusicArtists" FOREIGN KEY ("MusicArtistId") REFERENCES "MusicArtists" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MusicRecordingArtists_Credit" CHECK ("CreditOrder" >= 0 AND ("CreditName" IS NULL OR length(btrim("CreditName")) > 0))
);
CREATE INDEX "IX_MusicRecordingArtists_Artist" ON "MusicRecordingArtists" ("MusicArtistId", "MusicRecordingId");

CREATE TABLE "MusicTrackPlacements" (
    "WorkTrackId" bigint NOT NULL,
    "WorkId" bigint NOT NULL,
    "WorkEditionId" bigint NOT NULL,
    "DiscNumber" integer NOT NULL,
    "TrackNumber" integer NOT NULL,
    "DurationMs" bigint,
    "MusicRecordingId" bigint,
    CONSTRAINT "PK_MusicTrackPlacements" PRIMARY KEY ("WorkTrackId"),
    CONSTRAINT "UX_MusicTrackPlacements_Edition_Disc_Track" UNIQUE ("WorkEditionId", "DiscNumber", "TrackNumber"),
    CONSTRAINT "FK_MusicTrackPlacements_WorkTracks" FOREIGN KEY ("WorkTrackId", "WorkId") REFERENCES "WorkTracks" ("Id", "WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicTrackPlacements_MusicAlbums" FOREIGN KEY ("WorkId") REFERENCES "MusicAlbums" ("WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicTrackPlacements_Editions" FOREIGN KEY ("WorkEditionId", "WorkId") REFERENCES "WorkEditions" ("Id", "WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_MusicTrackPlacements_Recordings" FOREIGN KEY ("MusicRecordingId") REFERENCES "MusicRecordings" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_MusicTrackPlacements_Numbers" CHECK ("DiscNumber" > 0 AND "TrackNumber" > 0),
    CONSTRAINT "CK_MusicTrackPlacements_Duration" CHECK ("DurationMs" IS NULL OR "DurationMs" >= 0)
);
CREATE INDEX "IX_MusicTrackPlacements_Work" ON "MusicTrackPlacements" ("WorkId");
CREATE INDEX "IX_MusicTrackPlacements_Recording" ON "MusicTrackPlacements" ("MusicRecordingId") WHERE "MusicRecordingId" IS NOT NULL;

CREATE TABLE "WorkMusicArtists" (
    "WorkId" bigint NOT NULL,
    "MusicArtistId" bigint NOT NULL,
    "CreditOrder" integer NOT NULL DEFAULT 0,
    "CreditName" varchar(200),
    CONSTRAINT "PK_WorkMusicArtists" PRIMARY KEY ("WorkId","MusicArtistId"),
    CONSTRAINT "FK_WorkMusicArtists_MusicAlbums" FOREIGN KEY ("WorkId") REFERENCES "MusicAlbums" ("WorkId") ON DELETE RESTRICT,
    CONSTRAINT "FK_WorkMusicArtists_MusicArtists" FOREIGN KEY ("MusicArtistId") REFERENCES "MusicArtists" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "CK_WorkMusicArtists_Credit" CHECK ("CreditOrder" >= 0 AND ("CreditName" IS NULL OR length(btrim("CreditName")) > 0))
);
CREATE INDEX "IX_WorkMusicArtists_Artist" ON "WorkMusicArtists" ("MusicArtistId", "WorkId");

COMMIT;
